// Strongly consistent reads are supported for tables and local secondary
// indexes, not global secondary indexes. Global-table replication between
// regions has its own consistency behavior.

// Conceptual behavior during a network partition — not a database API.
Result handle(Operation op, PartitionState network, Policy policy) {
    if (network.cannotReachRequiredReplicas()) {
        if (policy.requiresLinearizableResult()) {
            return Result.retryableFailure(); // give up CAP availability here
        }
        Version local = applyLocally(op);
        scheduleRepairAndConflictResolution(local);
        return Result.accepted(local);        // result may not be linearizable
    }
    return executeWithNormalGuarantees(op);
}

